mapper.insert:
INSERT INTO moa.TB_COMM_POST (
    POST_SEQ
    , USR_ID
    , POST_TTL
    , POST_CN
    , POST_STAT
    , VIS_TYP
    , POST_DTM
    , FRST_REG_USER_ID
)
VALUES (
    #{postSeq}
    , #{usrId}
    , #{title}
    , #{description}
    , #{postStat}
    , #{visibility}
    , CURRENT_TIMESTAMP
    , #{frstRegUserId}
)

mapper.update:
UPDATE moa.TB_COMM_POST
   SET POST_TTL = #{title}
     , POST_CN = #{description}
     , LAST_MOD_USER_ID = #{lastModUserId}
     , LAST_MOD_DTM = TO_CHAR(CURRENT_TIMESTAMP, 'YYYYMMDDHH24MISS')
 WHERE POST_SEQ = #{postSeq}
   AND USR_ID = #{usrId}

UPDATE moa.TB_RCP
   SET RCP_CTG_CD = #{categoryCode}
     , COOK_MIN = #{cookingMinutes}
     , SERV_QTY = #{servings}
     , RCP_DIF_CD = #{difficultyCode}
     , LAST_MOD_USER_ID = #{lastModUserId}
     , LAST_MOD_DTM = TO_CHAR(CURRENT_TIMESTAMP, 'YYYYMMDDHH24MISS')
 WHERE POST_SEQ = #{postSeq}

UPDATE moa.TB_COMM_POST P
   SET POST_STAT = #{postDeleted}
     , LAST_MOD_USER_ID = #{usrId}
     , LAST_MOD_DTM = TO_CHAR(CURRENT_TIMESTAMP, 'YYYYMMDDHH24MISS')
 WHERE P.POST_SEQ = #{postSeq}
   AND P.USR_ID = #{usrId}
   AND P.POST_STAT IN (#{postActive}, 'ACTIVE')
   AND EXISTS (
        SELECT 1
          FROM moa.TB_RCP R
         WHERE R.POST_SEQ = P.POST_SEQ
   )

